trial.program_source:
def transform(grid):
    out=[r[:] for r in grid]
    h=len(grid); w=len(grid[0])
    horizontal=0; vertical=0
    for r in range(h):
        for c in range(w):
            v=grid[r][c]
            if not v: continue
            if c+1<w and grid[r][c+1] and grid[r][c+1]!=v: horizontal+=1
            if r+1<h and grid[r+1][c] and grid[r+1][c]!=v: vertical+=1
    if horizontal>=vertical:
        out[0]=[8]*w
    else:
        for row in out: row[-1]=8
    return out

